def S(N):
    """Computes S(N) = sum_{a=1}^{N} sum_{b=1}^{N} floor(ab / (N+1))"""
    sum_val = 0
    D = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sum_val += (a * b) // D
    return sum_val

def T(N):
    """Computes the target value T(N) = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

results = {}
for N in [1, 2, 3, 4]:
    s_n = S(N)
    t_n = T(N)
    results[N] = {
        "S(N)": s_n,
        "T(N)": t_n,
        "Match": s_n == t_n
    }

print("Results:")
for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, T(N) = {res['T(N)']}, Match = {res['Match']}")
